marks.before:
.chip .chgn { position: absolute; top: 8px; right: 8px; font-size: 11px; font-weight: 700; line-height: 18px; min-width: 18px; padding: 0 5px; border-radius: 999px; border: 1px solid var(--color-line-notice); background: var(--color-surface-notice); color: var(--color-text-warn); text-align: center; }
.ghost { font-size: 13px; border: 1px solid var(--color-line-control); color: var(--color-text-body); background: transparent; border-radius: 999px; padding: 3px 14px; cursor: pointer; }
.ask { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; border: 1px solid var(--color-key); color: var(--color-text-on-key); background: var(--color-key); border-radius: 999px; padding: 3px 14px 3px 10px; cursor: pointer; }
